# ============================================================
# 8) LP optimizer for one product-month
# ============================================================
def optimize_product_month(group, tolerance=1e-7):
    donors = (
        group[
            (group['potential_surplus_p90'] > tolerance)
            & group['lat'].notna()
            & group['long'].notna()
        ]
        .copy()
        .reset_index(drop=True)
    )

    receivers = (
        group[
            (group['predicted_deficit_p90'] > tolerance)
            & group['lat'].notna()
            & group['long'].notna()
        ]
        .copy()
        .reset_index(drop=True)
    )

    if donors.empty or receivers.empty:
        return pd.DataFrame(), {
            'lp_status': 'No feasible donor/receiver set',
            'max_transfer': 0.0
        }

    edge_rows = []

    for d_idx, donor in donors.iterrows():
        for r_idx, receiver in receivers.iterrows():

            if donor['hf_pk'] == receiver['hf_pk']:
                continue

            distance = float(
                haversine_km(
                    donor['lat'],
                    donor['long'],
                    receiver['lat'],
                    receiver['long']
                )
            )

            if not np.isfinite(distance):
                continue

            edge_rows.append(
                {
                    'd_idx': d_idx,
                    'r_idx': r_idx,
                    'distance_km': distance
                }
            )

    if not edge_rows:
        return pd.DataFrame(), {
            'lp_status': 'No feasible transfer edges',
            'max_transfer': 0.0
        }

    edges = pd.DataFrame(edge_rows)

    n_edges = len(edges)
    n_donors = len(donors)
    n_receivers = len(receivers)

    # --------------------------------------------------------
    # Donor and receiver inequality constraints
    # --------------------------------------------------------
    A_ub = lil_matrix(
        (n_donors + n_receivers, n_edges),
        dtype=float
    )

    b_ub = np.zeros(
        n_donors + n_receivers,
        dtype=float
    )

    for d_idx in range(n_donors):
        edge_ids = edges.index[
            edges['d_idx'] == d_idx
        ].tolist()

        for e in edge_ids:
            A_ub[d_idx, e] = 1.0

        b_ub[d_idx] = float(
            donors.loc[
                d_idx,
                'potential_surplus_p90'
            ]
        )

    for r_idx in range(n_receivers):
        row_idx = n_donors + r_idx

        edge_ids = edges.index[
            edges['r_idx'] == r_idx
        ].tolist()

        for e in edge_ids:
            A_ub[row_idx, e] = 1.0

        b_ub[row_idx] = float(
            receivers.loc[
                r_idx,
                'predicted_deficit_p90'
            ]
        )

    A_ub = A_ub.tocsr()

    bounds = [
        (0, None)
        for _ in range(n_edges)
    ]

    # --------------------------------------------------------
    # Stage 1: maximize total transferred quantity
    # linprog minimizes, so use -1 for every edge.
    # --------------------------------------------------------
    stage1 = linprog(
        c=-np.ones(n_edges),
        A_ub=A_ub,
        b_ub=b_ub,
        bounds=bounds,
        method='highs'
    )

    if not stage1.success:
        return pd.DataFrame(), {
            'lp_status': f'Stage 1 failed: {stage1.message}',
            'max_transfer': 0.0
        }

    max_transfer = float(
        np.sum(stage1.x)
    )

    if max_transfer <= tolerance:
        return pd.DataFrame(), {
            'lp_status': 'Zero optimal transfer',
            'max_transfer': 0.0
        }

    # --------------------------------------------------------
    # Stage 2: minimize distance while preserving max coverage
    # --------------------------------------------------------
    A_eq = np.ones(
        (1, n_edges),
        dtype=float
    )

    b_eq = np.array(
        [max_transfer],
        dtype=float
    )

    stage2 = linprog(
        c=edges['distance_km'].to_numpy(dtype=float),
        A_ub=A_ub,
        b_ub=b_ub,
        A_eq=A_eq,
        b_eq=b_eq,
        bounds=bounds,
        method='highs'
    )

    if not stage2.success:
        solution = stage1.x
        lp_status = (
            'Stage 2 failed; Stage 1 maximum-coverage solution used'
        )
    else:
        solution = stage2.x
        lp_status = 'Optimal'

    transfers = []

    for e_idx, qty in enumerate(solution):
        if qty <= tolerance:
            continue

        edge = edges.iloc[e_idx]

        donor = donors.iloc[
            int(edge['d_idx'])
        ]

        receiver = receivers.iloc[
            int(edge['r_idx'])
        ]

        transfers.append(
            {
                'date_parsed': donor['date_parsed'],
                'productID': donor['productID'],
                'donor_hf_pk': donor['hf_pk'],
                'receiver_hf_pk': receiver['hf_pk'],
                'transfer_quantity': float(qty),
                'distance_km': float(edge['distance_km']),
                'donor_potential_surplus_before': float(
                    donor['potential_surplus_p90']
                ),
                'receiver_predicted_deficit_before': float(
                    receiver['predicted_deficit_p90']
                ),
                'donor_lat': float(donor['lat']),
                'donor_long': float(donor['long']),
                'receiver_lat': float(receiver['lat']),
                'receiver_long': float(receiver['long'])
            }
        )

    return pd.DataFrame(transfers), {
        'lp_status': lp_status,
        'max_transfer': max_transfer
    }

# ============================================================
# 10) Validate LP constraints
# ============================================================
if transfer_plan.empty:
    print('No transfers were recommended.')
else:
    donor_used = (
        transfer_plan
        .groupby(
            ['date_parsed', 'productID', 'donor_hf_pk'],
            as_index=False
        )
        ['transfer_quantity']
        .sum()
        .rename(
            columns={
                'transfer_quantity': 'total_sent'
            }
        )
    )

    donor_limits = (
        df[
            df['potential_surplus_p90'] > 0
        ][
            [
                'date_parsed',
                'productID',
                'hf_pk',
                'potential_surplus_p90'
            ]
        ]
        .rename(
            columns={
                'hf_pk': 'donor_hf_pk'
            }
        )
    )

    donor_check = donor_used.merge(
        donor_limits,
        on=[
            'date_parsed',
            'productID',
            'donor_hf_pk'
        ],
        how='left'
    )

    donor_check['within_limit'] = (
        donor_check['total_sent']
        <= donor_check['potential_surplus_p90'] + 1e-5
    )

    receiver_received = (
        transfer_plan
        .groupby(
            ['date_parsed', 'productID', 'receiver_hf_pk'],
            as_index=False
        )
        ['transfer_quantity']
        .sum()
        .rename(
            columns={
                'transfer_quantity': 'total_received'
            }
        )
    )

    receiver_limits = (
        df[
            df['predicted_deficit_p90'] > 0
        ][
            [
                'date_parsed',
                'productID',
                'hf_pk',
                'predicted_deficit_p90'
            ]
        ]
        .rename(
            columns={
                'hf_pk': 'receiver_hf_pk'
            }
        )
    )

    receiver_check = receiver_received.merge(
        receiver_limits,
        on=[
            'date_parsed',
            'productID',
            'receiver_hf_pk'
        ],
        how='left'
    )

    receiver_check['within_limit'] = (
        receiver_check['total_received']
        <= receiver_check['predicted_deficit_p90'] + 1e-5
    )

    print(
        'All donor constraints valid:',
        donor_check['within_limit'].all()
    )

    print(
        'All receiver constraints valid:',
        receiver_check['within_limit'].all()
    )

    print(
        'Self transfers:',
        (
            transfer_plan['donor_hf_pk']
            == transfer_plan['receiver_hf_pk']
        ).sum()
    )

